import{_ as a,o as r,c as t,ag as i}from"./chunks/framework.DAaBRV8r.js";const h=JSON.parse('{"title":"Probability for Artificial Intelligence","description":"","frontmatter":{"layout":"doc","title":"Probability for Artificial Intelligence","date":"2026-09-04T00:00:00.000Z"},"headers":[],"relativePath":"pai.md","filePath":"pai.md"}'),o={name:"pai.md"};function n(l,e,s,c,p,f){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="probability-for-artificial-intelligence" tabindex="-1">Probability for Artificial Intelligence <a class="header-anchor" href="#probability-for-artificial-intelligence" aria-label="Permalink to &quot;Probability for Artificial Intelligence&quot;">​</a></h1><p>Professors <a href="https://profiles.stanford.edu/mehran-sahami" target="_blank" rel="noreferrer">Mehran Sahami</a> and <a href="https://profiles.stanford.edu/christopher-piech" target="_blank" rel="noreferrer">Chris Piech</a> from Stanford University are offering <a href="https://pai.stanford.edu/" target="_blank" rel="noreferrer">Probability for AI</a> to the public free of charge. As an alumnus of their <a href="https://codeinplace.stanford.edu/" target="_blank" rel="noreferrer">Code in Place</a> course, I was delighted to receive an invitation to apply.</p><p>It feels like a wonderful way to kick off retirement - keeping my mind active and engaged alongside a stack of good books.</p><p><strong>First day of class</strong>: October 9th 2026.</p><h3 id="application-process" tabindex="-1">Application process <a class="header-anchor" href="#application-process" aria-label="Permalink to &quot;Application process&quot;">​</a></h3><p>The application process started with taking two lessons on <a href="https://web.stanford.edu/class/archive/cs/cs109/cs109.1182/reader/2%20Probability.pdf" target="_blank" rel="noreferrer">Probability</a> and <a href="https://web.stanford.edu/class/archive/cs/cs109/cs109.1182/reader/3%20Conditional.pdf" target="_blank" rel="noreferrer">Conditional Probability</a>.</p><p>As part of the application, I submitted the required assignment <a href="https://pai.stanford.edu/pai/share/fpO8iOQvXD8cLu6QSbDg" target="_blank" rel="noreferrer">Word Detective</a>.</p><h3 id="acceptance" tabindex="-1">Acceptance <a class="header-anchor" href="#acceptance" aria-label="Permalink to &quot;Acceptance&quot;">​</a></h3><p>Pending</p>',9)])])}const b=a(o,[["render",n]]);export{h as __pageData,b as default};
